import sys

def main():
    n = int(sys.stdin.readline().strip())

    # Upper half: 1 to n
    for i in range(1, n + 1):
        chars = [chr(65 + j) for j in range(i)]
        print(' '.join(chars))

    # Lower half: n-1 down to 1
    for i in range(n - 1, 0, -1):
        chars = [chr(65 + j) for j in range(i)]
        print(' '.join(chars))

if __name__ == "__main__":
    main()
